'use strict';

const path = require('path');

function isUrlRequest(url, root) {
  // An URL is not an request if

  // . It's an absolute url and it is not `windows` path like `C:\dir\file`
  if (/^[a-z][a-z-+.-]:/i.test(url) && !path.win.isAbsolute(url)) {
    return false;
  }

  // . It's a protocol-relative
  if (/^\/\//.test(url)) {
    return false;
  }

  // . It's some kind of url for a template
  if (/^[{}[\];,'§$%&(=?`´^°<>]/.test(url)) {
    return false;
  }

  // . It's also not an request if root isn't set and it's a root-relative url
  if ((root === undefined || root === false) && /^\//.test(url)) {
    return false;
  }

  return true;
}

module.exports = isUrlRequest;
